"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,a)=>{a.r(t),a.d(t,{PAPERS:()=>i});let i=[{id:"2610.34283",title:"ChronoReplay: One Answer Interface Is Not Enough for Streaming Spatial Intelligence",up:42,href:"https://arxiv.org/abs/2610.34283",abstract:"Training a spatial VLM to answer which side an object lies on does not require it to preserve the metric displacement that determines that answer, while supervision for a distance estimate may leave categorical relations largely unconstrained. When post-training emphasizes one readout, improvements can therefore concentrate on that interface while transfer to others remains weak or even degrades; we call this observed specialization interface lock-in. ChronoReplay addresses it by replaying heterogeneous spatial supervision as chronologically ordered episodes, retaining source-native targets, a",published:"2026-10-25T00:00:00Z"},{id:"2610.33413",title:"AV-FABLE: Audio-Visual Manipulation Forensics in Long-Form Videos",up:39,href:"https://arxiv.org/abs/2610.33413",abstract:"Localized AI manipulations in long-form videos often affect brief events within otherwise authentic content, making video-level classification insufficient for forensic analysis. Existing audio-visual deepfake benchmarks largely focus on short talking-head clips, while long-form temporal forensics remains predominantly visual. We introduce AV-FABLE, a dual-timeline benchmark for sparse manipulations in open-scene long-form audio-visual videos. AV-FABLE contains 16,650 pristine--manipulated twin pairs (998 hours) created with 27 editing configurations, with separate audio and visual timelines t",published:"2026-10-24T00:00:00Z"},{id:"2610.36729",title:"Hy-Nomas: Towards Free-form Interactive World Generation",up:30,href:"https://arxiv.org/abs/2610.36729",abstract:"Interactive world generation requires models to follow successive commands while preserving relevant history and action consequences. We present Hy-Nomas, a video world model with an 8B diffusion backbone that supports free-form text instructions and continuous camera control across multiple interaction turns. It generates variable-length segments conditioned on current inputs and cached history. Our central design aligns structured video captions with action-aware causal attention: descriptive context remains accessible across segments, while action instructions are restricted to their intend",published:"2026-10-27T00:00:00Z"},{id:"2610.36068",title:"Rollback: Experience Backtracking in World Models for Policy Improvement",up:29,href:"https://arxiv.org/abs/2610.36068",abstract:"Action-conditioned world models offer a scalable alternative to costly real-world interaction for improving robot policies. However, existing world-model-based methods largely treat world models as forward-only surrogates of the physical environment, leaving untapped a capability no physical environment affords: rewinding to past decision points to explore counterfactual futures. We introduce Rollback, a policy improvement paradigm that turns world models from passive simulators into counterfactual engines: it rolls back to critical decision points, branches into alternative actions, and contr",published:"2026-10-26T00:00:00Z"},{id:"2610.21240",title:"Representation Redistribution in Sparse Autoencoders",up:27,href:"https://arxiv.org/abs/2610.21240",abstract:"Sparse autoencoders (SAEs) decompose language model activations into sparse features, but prompt transformations designed to preserve the underlying request can redistribute activity across them. A feature change observed on one transformed prompt need not recur, and even a recurring change need not affect a downstream computation. We introduce the redistribution sensitivity score (RSS), which identifies large feature responses that recur in a consistent direction, and evaluate the resulting supports on variants excluded from selection. Across 27 pretrained SAEs spanning eight language models,",published:"2026-10-15T00:00:00Z"},{id:"2610.33066",title:"OvisOCR3 Technical Report",up:24,href:"https://arxiv.org/abs/2610.33066",abstract:"We introduce OvisOCR3, a 0.8B model for a broad range of OCR-related tasks. OvisOCR3 unifies document parsing, general OCR, key information extraction (KIE), document figure captioning, and cross-page table reconstruction in a single model. We train the model on real and synthetic data through continued pretraining and use domain-balanced mid-training to balance supervision across tasks with different data volumes and response lengths. Multi-teacher on-policy distillation transfers expertise from five domain-specific 4B teachers into the shared model, followed by mixed-task reinforcement learn",published:"2026-10-20T00:00:00Z"},{id:"2610.36456",title:"LociArt: A Unified Paradigm for Free-Style Local Video Stylization",up:24,href:"https://arxiv.org/abs/2610.36456",abstract:"Video stylization typically transforms entire scenes, while local artistic editing requires precise region--style association, spatial control, and temporal consistency. We introduce LociArt, a unified paradigm for free-style local video stylization that explicitly specifies where to stylize and what style to apply while preserving non-target content. At its core, GRNStyle builds on Generative Refinement Networks (GRN) and introduces a polar style-aware mask that embeds style identities as equal-norm directions within selected regions. Complementary representation--geometry conditioning combin",published:"2026-10-27T00:00:00Z"},{id:"2610.37666",title:"ThinkWorld: World Imagination Reinforces Chain-of-Dynamics Reasoning",up:24,href:"https://arxiv.org/abs/2610.37666",abstract:"Vision-Language-Action (VLA) models have made substantial progress in robotic manipulation, but their generalization remains constrained by the diversity and coverage of action-labeled robot demonstrations. Human videos provide much broader behavioral and environmental experience, while learning from them faces a fundamental trade-off between scalable data and explicit action grounding. We introduce ThinkWorld, a VLA learning framework that grounds action reasoning in world dynamics and strengthens it through reinforcement learning with world imagination. ThinkWorld represents each action thou",published:"2026-10-27T00:00:00Z"},{id:"2610.22543",title:"On the SPOT: Enhancing Speculative Decoding for Diffusion Language Models via Commit-Order Prediction",up:18,href:"https://arxiv.org/abs/2610.22543",abstract:"Diffusion language models (DLMs) promise parallel text generation, but in practice face an unresolved speed-quality trade-off. Exact decoding fills in only one masked position per model pass, while faster multi-token decoding schemes are lossy. Speculative decoding is the standard lossless acceleration for autoregressive models. However, it does not transfer directly to DLMs, which must choose both what to generate and where. We show that this order is the missing piece: the model's own predictions from the previous pass already give the right token at over 90% of positions, but not which posi",published:"2026-10-26T00:00:00Z"},{id:"2610.33024",title:"Evolving to Match Capabilities: Improving Harness Self-Evolution via Skill Adaptation",up:17,href:"https://arxiv.org/abs/2610.33024",abstract:"Harness self-evolution offers a practical route for LLM agents to improve from execution experience without updating model parameters. Its effectiveness depends on whether models can successfully act on the guidance provided by their harnesses. However, we find that harness benefits are not uniform across model capabilities: skills that improve stronger models can provide little benefit or even degrade performance for weaker ones. Across seven models and three benchmarks, we identify 103 task-skill pairs where skills improve GPT-5.6-luna by 31.1 points but degrade Gemma-4-E4B by 8.8 points. In",published:"2026-10-10T00:00:00Z"},{id:"2610.24520",title:"HABIT-Bench: Evaluating Habit Induction from Longitudinal Weak Evidence in Agent Memory",up:13,href:"https://arxiv.org/abs/2610.24520",abstract:"In long-term interactions with large language model (LLM) agents, users reveal habits through their choices and actions. These habits capture implicit user information that agents must infer across conversations. However, individual observations may provide only partial evidence about a habit or when it applies. Retaining past interactions alone does not ensure that agents can infer habits and apply them appropriately. We introduce HABIT-Bench to evaluate how well agent memory systems infer habits from weak evidence and apply them to later requests. We construct synthetic user histories from t",published:"2026-10-20T00:00:00Z"},{id:"2610.29915",title:"CausalAlign: Causal Alignment of Video Generation Models for Consistent Ego-Motion",up:13,href:"https://arxiv.org/abs/2610.29915",abstract:"Diffusion-based video generation models (VGMs) can produce visually plausible videos, yet their camera ego-motion often drifts over long horizons. Camera ego-motion determines how the viewpoint changes between frames and is essential for maintaining consistent geometry and trajectories. To address this problem, we propose CausalAlign, a causal alignment framework with two components. First, we diagnose how precise ego motion is represented, used, and retained within VGMs using linear probes and causal interventions, revealing a rise-and-fall pattern during denoising. Second, we strengthen ego-",published:"2026-10-21T00:00:00Z"},{id:"2610.32046",title:"Can Test-Time Memory Evolution Outperform Test-Time Training for Scientific Discovery?",up:13,href:"https://arxiv.org/abs/2610.32046",abstract:"Recent test-time training (TTT) frameworks have enabled open-weight large language models (LLMs) to outperform inference-only frameworks powered by frontier models on scientific discovery tasks. However, TTT introduces additional computational cost for online weight updates during the discovery process, making computational efficiency an important consideration when scaling to larger models. This motivates us to explore an efficient test-time adaptation method for scientific discovery. We introduce Test-Time Memory Evolution (TTME), a plug-and-play test-time adaptation method, as an alternativ",published:"2026-10-23T00:00:00Z"},{id:"2610.34735",title:"iPrefBench: A User-Centric Benchmark for Personalized Mobile Use Agents",up:13,href:"https://arxiv.org/abs/2610.34735",abstract:"An agent that truly knows and acts on behalf of its user has been a long-standing promise of AI assistants. Computer-use agents bring this promise within reach by capably executing fully specified tasks across apps. However, real-world user requests are often underspecified. To act correctly for the particular user, an agent must infer some missing information from the user's activity history and ask for other information that only the user can provide, without making unsupported assumptions or burdening the user with unnecessary questions. We present iPrefBench, a benchmark for evaluating the",published:"2026-10-26T00:00:00Z"},{id:"2610.19025",title:"How Far Can Coding Agents Go in Visual Generation?",up:11,href:"https://arxiv.org/abs/2610.19025",abstract:"Modern image generation largely relies on specialized generative models that leave the process of image construction implicit in learned parameters. We explore an alternative: general-purpose coding agents that construct images through executable programs. Our study of zero-shot drawing on AgentDrawBench, a 200-prompt benchmark, reveals a distinctive capability profile. Agents excel at preserving structure and satisfying precise visual constraints, achieving competitive results in domains where compositional accuracy matters more than photorealistic appearance, while remaining limited in perce",published:"2026-10-13T00:00:00Z"},{id:"2610.33861",title:"ReGE: Stronger Agents through Experience Synthesis",up:11,href:"https://arxiv.org/abs/2610.33861",abstract:"Repeated attempts at interactive tasks uncover facts, useful operations, and failures that can inform subsequent execution. We introduce ReGE, a framework for turning this recorded experience into guidance for a fresh attempt. Its main implementation, ReGE-Syn, uses a single coach call to jointly synthesize bounded execution records and available artifacts into self-contained guidance, connecting task-specific findings with proposed actions and relevant pitfalls. A student starts from the task's initial environment state and adapts this guidance to current observations. Source generation, synt",published:"2026-10-24T00:00:00Z"},{id:"2610.32004",title:"CRM-Agent-Bench: Benchmarking Tool-Using Agents in Stateful Enterprise Environments",up:9,href:"https://arxiv.org/abs/2610.32004",abstract:"Deploying language agents in real applications demands more than the right answer: an agent must execute a multi-step business process correctly, follow domain-specific rules, and interact with a user across a dialogue, where the gap between saying and doing is the gap between a satisfied customer and a real loss. We argue that a deployable-agent benchmark should jointly assess four facets: the outcome an agent reaches, the trajectory it takes, its operational viability, and its policy compliance. Customer relationship management (CRM), where mutable records meet operational rules and conseque",published:"2026-10-23T00:00:00Z"},{id:"2610.33718",title:"RoboJev: An Open Vision-Language Judge for Robot Success Detection",up:9,href:"https://arxiv.org/abs/2610.33718",abstract:"Many robot manipulation videos do not indicate whether the task was successfully completed. RoboJev-27B is an open-weight vision-language model that takes a task instruction, 10 frames of a manipulation attempt, and (if available) final frames from auxiliary cameras and predicts whether the robot accomplished the task. RoboJev-27B is a variant of JEV-27B-VL, trained with a rank-32 LoRA adapter on the language model only (keeping the vision encoder frozen) using 52,598 episode records. It also uses a source-specific KL penalty that applies only to research data, anchoring predictions closer to ",published:"2026-10-24T00:00:00Z"},{id:"2610.34386",title:"ParetoRSI-Gym: Can AI Agents Improve Language Models Across Multiple Domains?",up:9,href:"https://arxiv.org/abs/2610.34386",abstract:"Recursive self-improvement (RSI) requires an agentic system to design, train, and evaluate its own successor. Data-driven post-training is a central part of that loop, yet existing evaluations measure it on a single benchmark, where an agent selects from a static pool or distills a stronger model to push one score up in one run. Real post-training is multi-domain, and a gain in one domain has to be weighed against a regression in another. We propose ParetoRSI-Gym, in which an agent searches for data, curates it, trains, reads back per-domain results, and repeats, with everything but the data h",published:"2026-10-25T00:00:00Z"},{id:"2610.35724",title:"MatAnyone-E: Sparse Memory Propagation for Efficient High-Resolution Video Matting",up:9,href:"https://arxiv.org/abs/2610.35724",abstract:"High-resolution video matting requires preserving fine details, such as hair strands and soft transparency, while maintaining consistency across frames. Memory-based methods achieve strong matting quality by matching current-frame features with information stored from earlier frames, but this process becomes increasingly costly as resolution grows. We present MatAnyone-E, an efficient extension of MatAnyone 2 that focuses computation where it is most needed. Our approach first performs low-resolution propagation to identify uncertain regions that require closer inspection and the memory candid",published:"2026-10-26T00:00:00Z"},{id:"2610.21561",title:"DialFork: Going Beyond Factuality to Evaluate Procedural Hallucination in Conversational Agents",up:8,href:"https://arxiv.org/abs/2610.21561",abstract:"Large language models (LLMs) deployed as conversational agents are increasingly expected to follow procedural logic. While factual hallucination has received extensive attention, a different failure mode has been overlooked: procedural hallucination, in which an agent produces individually fluent and factually plausible utterances while deviating from the intended conversational process. We introduce DialFork, the first benchmark to measure this failure mode on raw dialogue text. DialFork is built by forking conformant dialogues at controlled turn positions and injecting one of four hallucinat",published:"2026-10-15T00:00:00Z"},{id:"2610.33624",title:"RSI Arena: Towards Recursive Self-Improvement with Human Feedback",up:8,href:"https://arxiv.org/abs/2610.33624",abstract:"Can AI agents autonomously train useful language models and improve them using feedback from users? We introduce RSI Arena, a two-stage study of autonomous post-training as a step toward recursive self-improvement. Ten frontier models act as training agents, each starting from NVIDIA Nemotron 3.5 Lightning 30B-A3B Base. During a six-day first stage, each agent has 1,000 GPU-hours and $300 in API credit on a shared 64-GPU cluster, independently selecting data, implementing training procedures, and choosing checkpoints. We evaluate their models on 20 benchmarks and through blind human evaluation",published:"2026-10-24T00:00:00Z"},{id:"2610.37386",title:"Channel Selection for Mixture-of-Experts Decoding Needs No Calibration Data",up:8,href:"https://arxiv.org/abs/2610.37386",abstract:"Mixture-of-Experts (MoE) models are bottlenecked by loading routed-expert weights from memory during interactive decoding at small batch sizes. Because most intermediate channels in a routed expert contribute little to any single token, channel selectors predict which channels matter and read only their weights, typically keeping channels above a threshold calibrated on offline data. We show that channel selection needs no calibration data. First, a calibrated threshold does not fix how much a selector reads, because the number of channels passing it varies across inputs; Prox with thresholds ",published:"2026-10-27T00:00:00Z"},{id:"2610.33732",title:"Trust Mechanisms for Offline Generative AI at the Edge: A Connectivity-Regime Framework and an Empirical Study on a Raspberry Pi 5",up:7,href:"https://arxiv.org/abs/2610.33732",abstract:"Generative AI and large language models (LLMs) are moving into the Internet of Things, yet most deployments assume cloud connectivity, and many IoT settings have intermittent, restricted, or no connectivity. We propose a connectivity-regime framework (C0-C4), a taxonomy of inference-time trust mechanisms, and signed, versioned knowledge packs as the update channel for disconnected regimes, and evaluate them on a Raspberry Pi 5 running fully local retrieval-augmented generation under network isolation, with three Qwen2.5 model sizes, three context sizes, and 300 SQuAD 2.0 questions. An empirica",published:"2026-10-24T00:00:00Z"},{id:"W7171617880",title:"Machine-Speed Intrusion: A Detection Engineering Analysis of the July 2026 Hugging Face Agent Campaign",up:0,href:"https://doi.org/10.5281/zenodo.21686546",doi:"https://doi.org/10.5281/zenodo.21686546",year:2026,openalexId:"https://openalex.org/W7171617880"},{id:"W7171936549",title:"Could a Capability-Security Architecture Have Contained the July 2026 OpenAI-Hugging Face Agentic Exploit Chain?",up:0,href:"https://doi.org/10.5281/zenodo.21715175",doi:"https://doi.org/10.5281/zenodo.21715175",year:2026,openalexId:"https://openalex.org/W7171936549"},{id:"W7203931864",title:"hf-data-agent: a Hugging Face backed RAG data agent",up:0,href:"https://doi.org/10.5281/zenodo.22043399",doi:"https://doi.org/10.5281/zenodo.22043399",year:2026,openalexId:"https://openalex.org/W7203931864"}]}}]);